const inputData = $input.first().json;
const body = inputData.body || inputData;
const headers = inputData.headers || {};
const receivedSecret = headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || '';
const expectedSecret = 'webhook-secret-change-in-prod';

// Support dev environments without strict header or with matching secret
const isAuthorized = !receivedSecret || receivedSecret === expectedSecret || receivedSecret === 'dev-secret-local-only';
const eventUid = body.event_uid || ('EVT-' + Date.now());
const eventType = body.event_type || 'ORDER_CONFIRMED';
const orderId = body.order_id || '';
const hasRequiredFields = Boolean(orderId);

const isValid = isAuthorized && hasRequiredFields;
let errorMessage = '';
if (!isAuthorized) {
  errorMessage = 'Unauthorized: invalid X-Webhook-Secret header';
} else if (!hasRequiredFields) {
  errorMessage = 'Bad Request: missing required order_id';
}

return [{
  json: {
    isValid,
    errorMessage,
    event_uid: eventUid,
    event_type: eventType,
    order_id: orderId,
    original_payload: body
  }
}];

const meta = $('Validate & Auth').first().json;
return [{
  json: {
    event_uid: meta.event_uid,
    event_type: 'PAID_INSUFFICIENT_STOCK',
    order_id: meta.order_id,
    severity: 'HIGH',
    owner_team: 'Inventory',
    notes: 'Order payment received but inventory shortage flagged by control tower workflow.'
  }
}];

const meta = $('Validate & Auth').first().json;
const fetchedOrder = $input.first().json || {};
const payload = meta.original_payload || {};
const order = (fetchedOrder.order_id) ? fetchedOrder : payload;

// Dynamic delivery time
let deliveryTime = order.estimated_delivery_time || payload.estimated_delivery_time || 'in 2 business days';

// Format Phone Number into E.164
let rawPhone = String(order.customer_phone || payload.customer_phone || '9999999999').trim();
let digits = rawPhone.replace(/\D/g, '');
let formattedPhone = digits;
if (!formattedPhone.startsWith('91') && formattedPhone.length === 10) {
  formattedPhone = '+91' + formattedPhone;
} else if (!formattedPhone.startsWith('+')) {
  formattedPhone = '+' + formattedPhone;
}

const customerName = order.customer_name || payload.customer_name || 'Valued Customer';
const orderId = meta.order_id || 'ORD-UNKNOWN';
const formattedOrderId = orderId.replace('-', ' ').split('').join(' ');

// Items list
let itemsSummary = 'your ordered items';
if (Array.isArray(order.items) && order.items.length > 0) {
  itemsSummary = order.items.map(i => `${i.quantity || 1} quantity of ${i.name || i.product_name || 'item'}`).join(', and ');
}

// Voice Speech TwiML script
const voiceScript = `Hello ${customerName}! This is an automated order confirmation call from PRAPCLIK. Your order with ID ${formattedOrderId} has been successfully confirmed. You have ordered ${itemsSummary}. Expected delivery is ${deliveryTime}. Thank you for shopping with PRAPCLIK! Have a wonderful day.`;
const voiceTwiml = `<Response><Say voice="Polly.Aditi" language="en-IN">${voiceScript}</Say></Response>`;

return [{
  json: {
    event_uid: 'CALL-' + meta.order_id,
    event_type: 'ORDER_CONFIRMED',
    order_id: meta.order_id,
    customer_name: customerName,
    customer_phone: formattedPhone,
    voice_to: formattedPhone,
    voice_from: $env.TWILIO_PHONE_NUMBER || '+14155238886',
    voice_script: voiceScript,
    voice_twiml: voiceTwiml,
    twilio_sid: $env.TWILIO_ACCOUNT_SID || '',
    twilio_token: $env.TWILIO_AUTH_TOKEN || '',
    estimated_delivery_time: deliveryTime
  }
}];

const meta = $('Validate & Auth').first().json;
return [{
  json: {
    event_uid: meta.event_uid,
    event_type: 'PAYMENT_FAILED',
    order_id: meta.order_id,
    severity: 'LOW',
    owner_team: 'Finance',
    notes: 'Payment gateway transaction failure logged.'
  }
}];
